# -*- coding: utf-8 -*-
from lib import *
from content_guides1 import H_IG, H_FB, OFFICIEL

H_AD = ('<p>Si la demande de réexamen n’aboutit pas ou si le motif reste flou, voyez notre page '
        '<a href="/fr/compte-publicitaire-meta-restreint/">compte publicitaire Meta restreint</a>. Le prix vous est indiqué avant le début du travail, '
        'et vos accès restent chez vous.</p>')
H_REP = ('<p>Nous pouvons préparer des signalements clairs via les outils officiels : voir <a href="/fr/suppression-faux-comptes/">faux comptes et comptes frauduleux</a>. '
         'La décision de supprimer un compte revient toujours à la plateforme, et seulement si le compte enfreint ses règles.</p>')

guide('compte-publicitaire-facebook-desactive', 'facebook-ad-account-disabled',
    'Compte publicitaire Facebook désactivé : que faire ? | Unbanz', 'Compte publicitaire désactivé',
    'Compte publicitaire Facebook désactivé : que faire ?',
    'Si votre compte publicitaire Facebook est désactivé, ouvrez la Qualité du compte dans Meta Business Suite, notez le motif affiché et demandez un réexamen. Réglez d’abord les soldes impayés, activez la double authentification pour les administrateurs et ne créez pas de nouveau compte publicitaire pour contourner la restriction.',
    [('qualite', 'Commencer par la Qualité du compte',
      '<p>La Qualité du compte (dans Meta Business Suite ou le Gestionnaire de publicités) indique si votre compte publicitaire est restreint ou désactivé, avec le motif général et, quand c’est possible, un bouton pour demander un réexamen. Faites une capture d’écran avant de faire quoi que ce soit.</p>'),
     ('avant', 'À régler avant la demande',
      '<ul><li>Soldes impayés et moyen de paiement valide.</li><li>Double authentification activée pour tous les administrateurs.</li><li>Annonces et pages d’atterrissage conformes aux règles publicitaires.</li><li>Informations de l’entreprise cohérentes (nom, site, domaine vérifié).</li></ul>'),
     ('eviter', 'À éviter',
      '<ul><li>Créer de nouveaux comptes publicitaires ou profils pour contourner : c’est considéré comme du contournement.</li><li>Soumettre plusieurs demandes identiques.</li><li>Donner l’accès administrateur à un inconnu qui promet de « tout débloquer ».</li></ul>' + OFFICIEL)],
    [('Mon compte publicitaire Facebook est désactivé, comment le réactiver ?', 'Ouvrez la Qualité du compte, regardez le motif affiché et demandez un réexamen via le bouton prévu. Réglez les soldes impayés et activez la double authentification.'),
     ('Pourquoi mon compte publicitaire a-t-il été désactivé sans prévenir ?', 'Les causes courantes sont des annonces ne respectant pas les règles publicitaires, des paiements en échec, une activité jugée suspecte ou un profil administrateur restreint.'),
     ('Dois-je créer un nouveau compte publicitaire ?', 'Non. Créer un nouveau compte pour contourner une restriction est considéré comme du contournement et peut aggraver la situation.'),
     ('Un profil personnel restreint peut-il bloquer mon compte publicitaire ?', 'Oui, un profil restreint ne peut plus créer d’annonces, et les comptes dont il est le seul utilisateur peuvent être touchés. Ajoutez toujours un deuxième administrateur.'),
     ('Combien de temps faut-il pour un réexamen ?', 'Meta ne publie pas de délai fixe. Nous ne pouvons promettre aucune date.'),
     ('Combien coûte l’aide pour un compte publicitaire désactivé ?', 'Le prix dépend de la situation. Nous l’indiquons dans la discussion, après votre explication et avant le début du travail.')],
    ['business-manager-meta-restreint', 'page-facebook-restreinte', 'compte-facebook-desactive-faire-appel', 'compte-publicitaire-meta-restreint'], H_AD, svc='ad')

guide('business-manager-meta-restreint', 'business-manager-disabled',
    'Business Manager Meta restreint ou désactivé : que faire ? | Unbanz', 'Business Manager restreint',
    'Business Manager Meta restreint ou désactivé : que faire ?',
    'Si votre Business Manager (désormais portefeuille business) est restreint ou désactivé, ouvrez la Qualité du compte, vérifiez le motif et la vérification de l’entreprise et du domaine, puis demandez un réexamen. Vérifiez aussi les administrateurs et les paiements, et ne créez pas de nouveau portefeuille pour contourner la restriction.',
    [('quoi', 'Business Manager ou portefeuille business ?',
      '<p>Meta a renommé le Business Manager en <strong>portefeuille business</strong> dans une partie de ses interfaces. C’est le même ensemble d’actifs : Pages, comptes publicitaires, pixels, comptes Instagram, catalogues. Selon la version affichée, vous verrez l’un ou l’autre nom.</p>'),
     ('verifs', 'Ce qu’il faut vérifier',
      '<ul><li>Les informations de l’entreprise (nom, adresse, site) et leur cohérence.</li><li>La vérification du domaine et, si demandée, la vérification de l’entreprise.</li><li>Les administrateurs : chacun doit avoir la double authentification.</li><li>Les paiements : pas de solde impayé.</li><li>Les actifs : Pages et comptes publicitaires conformes aux règles.</li></ul>'),
     ('eviter', 'À éviter',
      '<p>Ne créez pas un nouveau portefeuille business en parallèle pour contourner une restriction et n’ajoutez pas de personnes inconnues comme administrateurs. Gardez toujours au moins deux administrateurs de confiance, afin qu’un seul profil restreint ne bloque pas toute l’activité.</p>' + OFFICIEL)],
    [('Pourquoi mon Business Manager est-il restreint ?', 'Les causes fréquentes sont des informations d’entreprise incohérentes, des paiements en échec, des annonces non conformes, ou un profil administrateur restreint.'),
     ('Business Manager ou portefeuille business, quelle différence ?', 'C’est la même chose : Meta utilise désormais « portefeuille business » dans de nombreuses interfaces.'),
     ('Dois-je vérifier mon entreprise ?', 'Si Meta le demande, oui. Utilisez des informations exactes et des documents authentiques, uniquement dans le flux officiel.'),
     ('Puis-je créer un nouveau Business Manager ?', 'Mieux vaut éviter si c’est pour contourner une restriction : cela peut aggraver la situation.'),
     ('Où trouver le Gestionnaire d’événements et mes pixels si l’accès est limité ?', 'Les pixels et événements sont rattachés aux actifs du portefeuille business. Si l’accès est restreint, résolvez d’abord la restriction.')],
    ['compte-publicitaire-facebook-desactive', 'page-facebook-restreinte', 'compte-publicitaire-meta-restreint'], H_AD, svc='ad')

guide('compte-facebook-desactive-faire-appel', 'guides/facebook-account-disabled-appeal',
    'Compte Facebook désactivé ou suspendu : comment faire appel ? | Unbanz', 'Faire appel : compte Facebook',
    'Compte Facebook désactivé ou suspendu : comment faire appel ?',
    'Facebook laisse en général 180 jours pour contester la suspension d’un compte ; passé ce délai ou après un refus, le compte est définitivement désactivé. Connectez-vous : vous êtes invité(e) à faire appel. Suivez toutes les étapes jusqu’à la confirmation, soyez factuel(le) et ne renvoyez pas la demande.',
    [('differences', 'Suspendu ou désactivé définitivement',
      '<p>Facebook emploie deux termes. <strong>Suspendu</strong> : vous pouvez faire appel dans un délai (en général 180 jours, variable selon les régions). <strong>Désactivé</strong> : étape définitive, après délai dépassé ou appel non concluant. Facebook peut aussi désactiver un compte directement pour des violations graves.</p>'),
     ('etapes', 'Contester la décision',
      '<ol><li>Faites une capture d’écran de la notification (date, jours restants) et gardez l’e-mail de Facebook.</li><li>Connectez-vous : Facebook vous propose de faire appel.</li><li>Faites les vérifications demandées (téléphone, contrôle de sécurité, selfie vidéo ou pièce d’identité) avec vos vraies informations.</li><li>Si un champ d’explication existe, restez bref et factuel.</li><li>Attendez : Facebook ne publie pas de délai. Ne renvoyez pas la demande.</li></ol>'),
     ('pages', 'Pages, groupes et activité professionnelle',
      '<p>Un profil désactivé peut affecter les Pages et comptes publicitaires dont il est administrateur. Une Page sans personne ayant le contrôle total est désactivée puis supprimée : ajoutez un second administrateur de confiance.</p>' + OFFICIEL)],
    [('Combien de temps ai-je pour faire appel sur Facebook ?', 'En général 180 jours, selon les régions. Après ce délai, le compte est définitivement désactivé.'),
     ('Puis-je récupérer mes données pendant la suspension ?', 'Souvent, oui. Vérifiez si la notification propose de télécharger vos informations.'),
     ('Dois-je créer un nouveau compte Facebook ?', 'Non. Meta peut désactiver les comptes créés pour contourner une restriction.'),
     ('Que se passe-t-il si mon appel est refusé ?', 'Facebook indique que le compte est alors définitivement désactivé et qu’un nouvel appel n’est pas possible. En Europe, un recours externe DSA existe : voir notre page.'),
     ('Ma Page sera-t-elle supprimée si mon profil est désactivé ?', 'Pas automatiquement, mais une Page sans administrateur ayant le contrôle total est désactivée puis supprimée.'),
     ('Combien de temps dure un appel Facebook ?', 'Facebook ne publie pas de délai. Nous ne pouvons promettre aucune date.')],
    ['compte-facebook-pirate-que-faire', 'page-facebook-restreinte', 'droit-de-recours-dsa-meta', 'compte-facebook-desactive'], H_FB)

guide('compte-facebook-pirate-que-faire', 'guides/hacked-facebook-account-recovery',
    'Compte Facebook piraté : comment le récupérer | Unbanz', 'Compte Facebook piraté',
    'Compte Facebook piraté : comment le récupérer ?',
    'Pour récupérer un compte Facebook piraté, allez sur facebook.com/hacked depuis un appareil déjà utilisé et suivez les étapes. Si l’e-mail ou le téléphone a été changé, cherchez le message de Facebook pour annuler la modification, ou utilisez « Trouver votre compte » avec une ancienne adresse. Facebook peut demander un selfie vidéo ou une pièce d’identité.',
    [('start', 'Commencer par facebook.com/hacked',
      '<p>Sur un téléphone ou un ordinateur déjà utilisé pour Facebook, ouvrez <strong>facebook.com/hacked</strong> et suivez les étapes. Un appareil et un réseau familiers facilitent la reconnaissance.</p>'),
     ('modif', 'Si l’e-mail ou le téléphone a été changé',
      '<p>Cherchez dans votre boîte un e-mail de Facebook sur la modification : il contient généralement un lien pour l’annuler et sécuriser le compte. Sinon, utilisez la recherche de compte (facebook.com/login/identify) avec toute adresse, tout numéro ou tout pseudo ayant déjà servi sur le profil. Facebook peut demander une vérification (selfie vidéo, pièce d’identité) uniquement dans son propre parcours.</p>'),
     ('apres', 'Une fois de retour',
      '<ul><li>Changez le mot de passe du compte et celui de l’e-mail lié.</li><li>Activez la double authentification avec une application d’authentification.</li><li>Déconnectez les appareils inconnus.</li><li>Retirez les administrateurs inconnus de vos Pages et comptes publicitaires.</li><li>Prévenez vos amis d’ignorer les messages envoyés pendant le piratage.</li></ul><p>En France, voir aussi <a href="https://www.cybermalveillance.gouv.fr/" rel="noopener" target="_blank">cybermalveillance.gouv.fr</a>.</p>')],
    [('Mon compte Facebook a été piraté, que faire ?', 'Allez sur facebook.com/hacked depuis un appareil déjà utilisé et suivez les étapes. Cherchez aussi le message de Facebook sur la modification d’e-mail.'),
     ('Le pirate a changé mon e-mail et mon numéro, c’est fini ?', 'Non. Utilisez la recherche de compte avec une ancienne adresse ou un ancien numéro, puis confirmez votre identité par selfie vidéo ou pièce d’identité si Facebook le demande.'),
     ('Quelqu’un peut-il récupérer mon compte à ma place ?', 'Commencez par le parcours officiel de Facebook et gardez vos codes pour vous. Méfiez-vous des offres de « hackers » : voir notre page sur les arnaques.'),
     ('Dois-je donner mon mot de passe pour récupérer mon compte ?', 'Non. Ne partagez jamais votre mot de passe ni vos codes de connexion.'),
     ('Mon compte piraté a été désactivé, que faire ?', 'Récupérez d’abord l’accès, puis faites appel de la désactivation. Voir notre guide sur l’appel d’un compte Facebook désactivé.')],
    ['compte-facebook-desactive-faire-appel', 'faux-hackers-arnaque-recuperation-compte', 'page-facebook-restreinte', 'compte-facebook-desactive'], H_FB)

guide('page-facebook-restreinte', 'guides/facebook-page-restricted',
    'Page Facebook restreinte ou non publiée : comment la rétablir | Unbanz', 'Page Facebook restreinte',
    'Page Facebook restreinte ou non publiée : que faire ?',
    'Quand une Page Facebook disparaît ou perd des fonctions, la première question est de savoir si un administrateur l’a dépubliée ou si Meta l’a restreinte. Si elle a été dépubliée, vous pouvez la republier ; si Meta l’a restreinte, consultez l’état de la Page et demandez un réexamen. Gardez au moins deux administrateurs de confiance.',
    [('qui', 'Dépubliée par un administrateur ou restreinte par Meta ?',
      '<p>Si une personne avec accès a dépublié la Page, il suffit de la republier depuis les paramètres de la Page. Si Meta l’a restreinte, un message ou une notification apparaît dans l’état de la Page, avec en général une option pour demander un réexamen.</p>'),
     ('admin', 'Contrôle de la Page',
      '<p>Une Page doit toujours avoir au moins une personne ayant le contrôle total. Sans cela, elle est désactivée puis programmée pour suppression. Ajoutez un second administrateur de confiance et ne reposez pas l’entreprise sur un seul profil personnel.</p>'),
     ('pub', 'Si des publicités sont concernées',
      '<p>Une Page restreinte peut empêcher la diffusion de publicités. Voir <a href="/fr/compte-publicitaire-facebook-desactive/">compte publicitaire Facebook désactivé</a> et <a href="/fr/business-manager-meta-restreint/">Business Manager restreint</a>.</p>' + OFFICIEL)],
    [('Ma Page Facebook a disparu, est-elle supprimée ?', 'Elle peut avoir été dépubliée par un administrateur ou restreinte par Meta. Regardez l’état de la Page et les notifications.'),
     ('Comment republier une Page Facebook ?', 'Dans les paramètres de la Page, modifiez la visibilité pour la publier de nouveau, si elle a été dépubliée par un administrateur.'),
     ('Que faire si Meta a restreint ma Page ?', 'Ouvrez l’état de la Page, notez le motif et demandez un réexamen si l’option est proposée.'),
     ('Pourquoi ma Page a-t-elle été désactivée par manque d’administrateur ?', 'Une Page sans personne ayant le contrôle total est désactivée puis programmée pour suppression. Ajoutez un second administrateur.'),
     ('Une Page restreinte bloque-t-elle mes publicités ?', 'Elle peut limiter ou empêcher les publicités liées. Résolvez d’abord la restriction de la Page.')],
    ['compte-publicitaire-facebook-desactive', 'business-manager-meta-restreint', 'compte-facebook-desactive-faire-appel', 'compte-facebook-desactive'], H_FB)

guide('pseudo-instagram-deja-pris-compte-inactif', 'inactive-instagram-username',
    'Pseudo Instagram déjà pris par un compte inactif : que faire ? | Unbanz', 'Pseudo pris, compte inactif',
    'Pseudo Instagram déjà pris par un compte inactif : que faire ?',
    'Instagram ne propose pas de procédure publique pour « réclamer » un pseudo occupé par un compte inactif. Selon la situation, les voies possibles sont un signalement de marque ou de propriété intellectuelle, un signalement d’usurpation si quelqu’un se fait passer pour vous, ou les processus propres à la plateforme. Évitez les bots, les achats de comptes et les faux signalements.',
    [('pourquoi', 'Pourquoi un compte inactif garde son pseudo',
      '<p>Un compte peut rester en ligne indéfiniment sans publication, tant qu’il n’est pas supprimé et qu’il ne viole aucune règle. L’inactivité seule n’est pas un motif de retrait.</p>'),
     ('voies', 'Les voies possibles',
      '<ul><li><strong>Marque ou propriété intellectuelle</strong> : si le pseudo correspond à une marque déposée dont vous êtes titulaire, un signalement dédié existe.</li><li><strong>Usurpation</strong> : si le compte se fait passer pour vous ou votre marque.</li><li><strong>Contact direct</strong> : écrire poliment au titulaire si le compte est actif.</li></ul><p>Chaque voie suppose de pouvoir justifier votre demande.</p>'),
     ('non', 'Ce qu’il ne faut pas faire',
      '<ul><li>Utiliser des bots ou des outils de « sniping » de pseudos.</li><li>Acheter un compte à un inconnu.</li><li>Déposer de faux signalements ou signaler en masse.</li></ul>'),
     ('remboursement', 'Politique de remboursement',
      '<p>Remboursement intégral à 100\u00a0% si la réclamation du nom d’utilisateur échoue. Une réclamation échoue lorsque le pseudo n’est pas obtenu sur votre profil. Cette politique concerne uniquement les réclamations de pseudo.</p>')],
    [('Peut-on récupérer un pseudo Instagram d’un compte inactif ?', 'Parfois, par les voies officielles (marque, usurpation). Il n’existe pas de procédure publique pour « réclamer » simplement un pseudo.'),
     ('Instagram libère-t-il les pseudos des comptes inactifs ?', 'Instagram ne publie pas de règle de libération automatique : un compte inactif peut garder son pseudo.'),
     ('Peut-on acheter un pseudo Instagram ?', 'Acheter un compte est interdit par les règles d’Instagram et risqué : évitez-le.'),
     ('Un signalement de marque peut-il fonctionner ?', 'Seulement si vous êtes titulaire de la marque et que le compte porte atteinte à vos droits. Ne déposez pas de faux signalements.'),
     ('Unbanz peut-il m’aider à obtenir un pseudo ?', 'Nous regardons si une voie officielle est adaptée et vous le disons honnêtement. Le prix est indiqué avant le début du travail.'),
     ('Que se passe-t-il si la réclamation de mon pseudo échoue ?', 'Vous êtes remboursé(e) intégralement, à 100\u00a0%. Si le pseudo n’est pas obtenu sur votre profil, nous vous remboursons la totalité de ce que vous avez payé pour la réclamation.')],
    ['pseudo-instagram-indisponible-sans-compte', 'usurpation-identite-instagram', 'pseudo-instagram'], '<p>Voyez notre page <a href="/fr/pseudo-instagram/">pseudo Instagram</a> : nous vous disons franchement si c’est jouable, avant tout travail. Le pseudo va sur votre propre profil, aucun compte ne change de mains.</p>', svc='username')

guide('pseudo-instagram-indisponible-sans-compte', 'instagram-username-not-available-but-no-account',
    'Pseudo Instagram indisponible alors que le compte n’existe pas | Unbanz', 'Pseudo indisponible sans compte',
    'Pseudo Instagram indisponible alors qu’aucun compte ne s’affiche.',
    'Un pseudo peut être indisponible sans qu’aucun profil ne s’affiche : le compte est peut-être désactivé, en cours de suppression (jusqu’à 90 jours), récemment renommé, ou le mot est bloqué. Attendez quelques semaines puis réessayez ; si le pseudo correspond à votre marque, une voie officielle peut exister.',
    [('raisons', 'Les explications possibles',
      '<ul><li>Le compte est <strong>désactivé</strong> par son titulaire ou par Instagram.</li><li>Il est <strong>en cours de suppression</strong> (jusqu’à 90 jours).</li><li>Il a été <strong>renommé récemment</strong> et le pseudo est retenu un temps.</li><li>Le mot est <strong>bloqué</strong> (mots interdits ou réservés).</li></ul>'),
     ('faire', 'Que faire',
      '<p>Essayez une variante proche, attendez puis réessayez, et vérifiez qu’aucune faute de frappe ne vous induit en erreur. Si le pseudo est lié à votre marque, voyez <a href="/fr/pseudo-instagram-deja-pris-compte-inactif/">les voies pour un pseudo pris par un compte inactif</a>.</p>'),
     ('remboursement', 'Politique de remboursement',
      '<p>Remboursement intégral à 100\u00a0% si la réclamation du nom d’utilisateur échoue. Une réclamation échoue lorsque le pseudo n’est pas obtenu sur votre profil. Cette politique concerne uniquement les réclamations de pseudo.</p>')],
    [('Pourquoi mon pseudo est-il indisponible sans compte visible ?', 'Le compte peut être désactivé, en suppression, renommé récemment, ou le mot peut être bloqué.'),
     ('Combien de temps faut-il pour qu’un pseudo se libère ?', 'Instagram ne publie pas de durée. Une suppression peut prendre jusqu’à 90 jours.'),
     ('Peut-on forcer la libération d’un pseudo ?', 'Pas directement. Il existe des voies officielles (marque, usurpation) si les conditions sont remplies.'),
     ('Un mot peut-il être bloqué ?', 'Oui, certains mots ou combinaisons sont bloqués ou réservés.'),
     ('Dois-je utiliser un outil de surveillance de pseudo ?', 'Évitez les bots et outils de « sniping » : ils vont à l’encontre des règles et peuvent mettre votre compte en danger.'),
     ('Que se passe-t-il si la réclamation de mon pseudo échoue ?', 'Vous êtes remboursé(e) intégralement, à 100\u00a0%. Si le pseudo n’est pas obtenu sur votre profil, nous vous remboursons la totalité de ce que vous avez payé pour la réclamation.')],
    ['pseudo-instagram-deja-pris-compte-inactif', 'compte-instagram-supprime-ou-desactive', 'pseudo-instagram'], '<p>Voyez notre page <a href="/fr/pseudo-instagram/">pseudo Instagram</a>. Nous vous disons franchement si c’est jouable, avant le début du travail.</p>', svc='username')

guide('comment-signaler-faux-compte-instagram', 'fake-instagram-account-using-my-photos',
    'Comment signaler un faux compte Instagram qui utilise vos photos | Unbanz', 'Signaler un faux compte',
    'Comment signaler un faux compte Instagram ?',
    'Pour signaler un faux compte Instagram, ouvrez le profil, touchez les trois points puis « Signaler », et choisissez le motif qui correspond : usurpation d’identité, arnaque, ou contenu volé. Faites des captures d’écran avant, et si seules vos photos sont utilisées, un signalement pour atteinte au droit d’auteur peut aussi convenir.',
    [('etapes', 'Signaler le profil',
      '<ol><li>Faites des captures d’écran du profil, des publications et des messages.</li><li>Ouvrez le profil, touchez les trois points, puis « Signaler ».</li><li>Choisissez le motif le plus proche (par exemple « Se fait passer pour quelqu’un d’autre »).</li><li>Suivez les étapes et indiquez si le compte vous concerne vous ou une marque.</li></ol><p>Les intitulés exacts varient selon la version de l’application.</p>'),
     ('photos', 'Si seules vos photos sont utilisées',
      '<p>Si le compte ne prétend pas être vous mais utilise vos photos, un signalement pour atteinte au droit d’auteur (formulaire du centre d’aide) peut être plus adapté qu’un signalement d’usurpation.</p>'),
     ('france', 'En France',
      '<p>Si le faux compte sert à une arnaque, vous pouvez le signaler sur <a href="https://www.internet-signalement.gouv.fr/" rel="noopener" target="_blank">Pharos</a>, ou déposer plainte. Pour une arnaque financière, voir aussi <a href="https://www.cybermalveillance.gouv.fr/" rel="noopener" target="_blank">cybermalveillance.gouv.fr</a>. Voir aussi <a href="/fr/usurpation-identite-instagram/">usurpation d’identité</a>.</p>')],
    [('Comment signaler un faux compte Instagram ?', 'Ouvrez le profil, touchez les trois points, « Signaler », puis le motif qui correspond. Faites des captures d’écran avant.'),
     ('Quelqu’un utilise mes photos sur Instagram, que faire ?', 'Signalez le profil, et si le compte ne se fait pas passer pour vous, un signalement pour atteinte au droit d’auteur peut être adapté.'),
     ('Combien de temps faut-il à Instagram pour supprimer un faux compte ?', 'Instagram ne publie pas de délai. Il supprime un compte uniquement s’il enfreint ses règles.'),
     ('Dois-je bloquer le faux compte avant de le signaler ?', 'Faites d’abord vos captures d’écran, puis signalez et bloquez.'),
     ('Peut-on porter plainte pour un faux compte ?', 'Si le faux compte usurpe votre identité ou sert une arnaque, cela peut constituer une infraction. Rapprochez-vous de la police ou de la gendarmerie avec vos preuves.')],
    ['usurpation-identite-instagram', 'suppression-faux-comptes', 'harcelement-compte-signalement', 'faux-hackers-arnaque-recuperation-compte'], H_REP, svc='ban')

guide('snapchat-compte-verrouille-duree', 'how-long-does-a-snapchat-lock-last',
    'Snapchat compte verrouillé : combien de temps ? | Unbanz', 'Snapchat verrouillé : durée',
    'Snapchat compte verrouillé : combien de temps ça dure ?',
    'Un verrouillage temporaire de compte Snapchat dure en général autour de 48 heures, souvent lié à l’usage d’applications tierces, mais Snapchat ne s’engage sur aucune durée. Un verrouillage définitif ne se lève pas tout seul : il faut déposer une demande via le formulaire officiel de Snapchat. Supprimez d’abord toute application tierce.',
    [('types', 'Temporaire ou définitif',
      '<ul><li><strong>Temporairement verrouillé</strong> : une attente est nécessaire, souvent d’environ 48 heures pour les verrouillages liés à des applications tierces.</li><li><strong>Définitivement verrouillé</strong> : une demande de réexamen est nécessaire.</li></ul>'),
     ('faire', 'Que faire',
      '<ol><li>Supprimez ou déconnectez les applications tierces qui se connectent avec vos identifiants.</li><li>Attendez la fin de la période, sans multiplier les tentatives de connexion.</li><li>Ouvrez la page officielle de comptes Snapchat (accounts.snapchat.com) et utilisez l’option de déverrouillage.</li><li>Pour un verrouillage définitif, déposez la demande via le formulaire officiel.</li></ol>' + OFFICIEL)],
    [('Combien de temps un compte Snapchat reste-t-il verrouillé ?', 'Un verrouillage temporaire dure en général autour de 48 heures, mais Snapchat ne s’engage sur aucune durée.'),
     ('Pourquoi mon compte Snapchat est-il verrouillé ?', 'Souvent à cause d’applications tierces, de connexions inhabituelles ou d’activité signalée.'),
     ('Un verrouillage définitif peut-il être levé ?', 'Il existe une procédure de réexamen via le formulaire officiel. L’issue dépend de Snapchat.'),
     ('Dois-je supprimer des applications avant de me reconnecter ?', 'Oui, supprimez toute application tierce qui se connecte avec vos identifiants.'),
     ('Puis-je créer un nouveau compte Snapchat en attendant ?', 'Pour un compte définitivement verrouillé, évitez de contourner la mesure : cela peut compliquer la suite.')],
    ['compte-snapchat-verrouille', 'faux-hackers-arnaque-recuperation-compte'], '<p>Voyez notre page <a href="/fr/compte-snapchat-verrouille/">compte Snapchat verrouillé</a>. Le prix vous est indiqué avant le début du travail.</p>')

guide('faux-hackers-arnaque-recuperation-compte', 'guides/account-recovery-scams-fake-hackers-warning',
    'Arnaque à la récupération de compte Instagram : comment l’éviter | Unbanz', 'Arnaques de récupération',
    'Arnaque à la récupération de compte Instagram : comment l’éviter.',
    'Les arnaques à la récupération de compte visent surtout les personnes qui ont perdu leur compte : faux « hackers », faux « support Instagram », liens de connexion piégés. Règle simple : personne n’a besoin de votre mot de passe ni de vos codes pour vous aider, et aucun service sérieux ne vous demandera de payer à l’aveugle ou de vous connecter via son lien.',
    [('signes', 'Les signes d’une arnaque',
      '<ul><li>On vous contacte en message privé ou dans les commentaires sans que vous ayez demandé quoi que ce soit.</li><li>On vous demande votre mot de passe, un code SMS ou un accès à votre e-mail.</li><li>On vous promet une récupération « immédiate » ou « assurée ».</li><li>On prétend connaître quelqu’un chez Meta.</li><li>On vous demande un paiement en cryptomonnaie ou par carte-cadeau sans site, ni adresse e-mail, ni conditions.</li></ul>'),
     ('verifier', 'Comment vérifier un service',
      '<p>Un service sérieux a un site, une adresse e-mail, des conditions écrites, ne demande jamais votre mot de passe et vous explique le prix avant de commencer. Vous le contactez vous-même, et non l’inverse. Voyez <a href="/fr/unbanz-est-il-fiable/">Unbanz est-il fiable ?</a> pour la façon dont nous travaillons.</p>'),
     ('victime', 'Si vous avez déjà payé ou donné des accès',
      '<p>Changez immédiatement vos mots de passe, activez la double authentification, gardez les preuves et signalez l’arnaque : <a href="https://www.cybermalveillance.gouv.fr/" rel="noopener" target="_blank">cybermalveillance.gouv.fr</a> propose des conseils, et la plateforme Pharos permet de signaler des contenus ou comportements illicites en ligne. Votre banque peut vous conseiller en cas de paiement.</p>')],
    [('Comment reconnaître une arnaque à la récupération de compte Instagram ?', 'On vous contacte en premier, on vous demande vos identifiants ou un paiement opaque, et on vous promet un résultat assuré.'),
     ('Un hacker peut-il vraiment récupérer mon compte Instagram ?', 'Méfiez-vous : ces offres sont souvent des arnaques. Les voies officielles (instagram.com/hacked, contestation) sont gratuites.'),
     ('Dois-je donner mon mot de passe pour récupérer mon compte ?', 'Non, jamais. Ni à un « hacker », ni à un « support », ni à qui que ce soit.'),
     ('Instagram a-t-il un numéro de téléphone pour m’aider ?', 'Il n’existe pas de ligne téléphonique générale pour les utilisateurs. Méfiez-vous des numéros trouvés en ligne. Voir notre page sur le contact avec le support en France.'),
     ('Où signaler une arnaque en France ?', 'Vous pouvez consulter cybermalveillance.gouv.fr, signaler sur Pharos, et déposer plainte auprès de la police ou de la gendarmerie.')],
    ['contacter-instagram-meta-support-france', 'compte-instagram-pirate-que-faire', 'unbanz-est-il-fiable', 'recuperer-compte-instagram'], H_IG)

guide('sextorsion-instagram-que-faire', 'guides/sextortion-what-to-do-on-instagram',
    'Sextorsion sur Instagram : que faire tout de suite | Unbanz', 'Sextorsion Instagram',
    'Sextorsion sur Instagram : que faire tout de suite ?',
    'Si vous êtes victime de chantage à la sextorsion sur Instagram : ne payez pas, arrêtez de répondre, gardez les preuves, puis bloquez et signalez le compte. En France, le 3018 (gratuit, confidentiel) et la plateforme Pharos existent, et vous pouvez déposer plainte. En cas de danger immédiat, appelez le 17 ou le 112. Ce n’est pas de votre faute.',
    [('urgence', 'Les premiers gestes',
      '<ol><li><strong>Ne payez pas</strong> et n’envoyez pas d’autres images : payer met rarement fin aux menaces.</li><li><strong>Gardez les preuves</strong> : captures d’écran des messages, du profil et des demandes d’argent, avant de bloquer. Notez pseudos, liens et dates.</li><li><strong>Bloquez et signalez</strong> le compte depuis la conversation.</li><li><strong>Parlez-en</strong> à une personne de confiance.</li></ol>'),
     ('france', 'En France : qui contacter',
      '<ul><li><strong>3018</strong> : numéro national contre le harcèlement et les violences numériques, gratuit et confidentiel. Il peut aider à faire retirer des contenus.</li><li><strong>Pharos</strong> (<a href="https://www.internet-signalement.gouv.fr/" rel="noopener" target="_blank">internet-signalement.gouv.fr</a>) : signalement officiel des contenus et comportements illicites sur Internet.</li><li><strong>Police ou gendarmerie</strong> : pour déposer plainte. En danger immédiat : <strong>17</strong> ou <strong>112</strong>.</li></ul>'),
     ('images', 'Empêcher la diffusion d’images',
      '<p>L’outil gratuit <strong>StopNCII.org</strong> permet aux adultes de créer une empreinte numérique d’une image sur leur propre appareil, sans la téléverser, afin que les plateformes partenaires puissent la détecter. Pour des images prises avant 18 ans, le service <strong>Take It Down</strong> du NCMEC fonctionne de façon similaire.</p>'),
     ('compte', 'Sécuriser votre compte',
      '<p>Passez le compte en privé, triez les abonnés, activez les mots masqués, limitez qui peut vous écrire, changez le mot de passe et activez la double authentification.</p>'),
     ('parents', 'Pour les parents',
      '<p>Restez calme et faites comprendre à votre enfant qu’il n’est pas en faute. Aidez-le à couper le contact, à garder les preuves et à signaler. Pour les mineurs, le 3018 et la police sont les premiers interlocuteurs.</p>')],
    [('Que faire en cas de chantage à la sextorsion sur Instagram ?', 'Ne payez pas, arrêtez de répondre, gardez les preuves, bloquez et signalez le compte, et contactez le 3018 ou la police.'),
     ('Payer fait-il cesser le chantage ?', 'Rarement. Les demandes continuent souvent après un paiement.'),
     ('Le 3018 est-il réservé aux mineurs ?', 'Non. Il s’adresse aux jeunes, aux parents et aux professionnels, et aux personnes touchées par le harcèlement et les violences numériques.'),
     ('Comment signaler sur Pharos ?', 'Rendez-vous sur internet-signalement.gouv.fr et décrivez le contenu ou le comportement, avec les liens et captures d’écran.'),
     ('StopNCII envoie-t-il mon image ?', 'Non. L’empreinte est créée sur votre appareil, l’image n’est pas envoyée.'),
     ('Instagram peut-il supprimer le compte du maître-chanteur ?', 'Vous pouvez le signaler. Meta ne publie pas de délai, c’est pourquoi il faut aussi contacter la police.')],
    ['harcelement-compte-signalement', 'comment-signaler-faux-compte-instagram', 'compte-instagram-pirate-que-faire'],
    '<p>Si vous le souhaitez, nous pouvons préparer les signalements auprès de la plateforme, en plus des démarches auprès des autorités. Voyez <a href="/fr/harcelement-compte-signalement/">harcèlement et signalement</a>. Ne nous envoyez jamais d’images intimes : une description et le lien du compte suffisent.</p>', svc='ban')
